CREATE OR REPLACE FUNCTION public.admin_change_contributor_slug(p_contributor_id uuid, p_new_slug text, p_reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id   uuid := auth.uid();
  v_admin_role text;
  v_old_slug   text;
  v_new_slug   text := lower(trim(p_new_slug));
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO v_admin_role
  FROM public.profiles
  WHERE id = v_admin_id;

  IF v_admin_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;

  IF v_new_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])?$' THEN
    RAISE EXCEPTION 'invalid_slug_format' USING ERRCODE = '22023';
  END IF;

  SELECT contributor_slug INTO v_old_slug
  FROM public.profiles
  WHERE id = p_contributor_id;

  IF v_old_slug IS NULL THEN
    RAISE EXCEPTION 'contributor_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_old_slug = v_new_slug THEN
    RAISE EXCEPTION 'slug_unchanged' USING ERRCODE = '22023';
  END IF;

  UPDATE public.profiles
     SET contributor_slug   = v_new_slug,
         handle_changed_at  = now()
   WHERE id = p_contributor_id;

  INSERT INTO public.admin_actions (
    actor_id, action, target_type, target_id, metadata
  ) VALUES (
    v_admin_id,
    'contributor_slug_override',
    'profiles',
    p_contributor_id::text,
    jsonb_build_object(
      'old_slug', v_old_slug,
      'new_slug', v_new_slug,
      'reason',   coalesce(p_reason, '')
    )
  );

  INSERT INTO public.activity_log (
    contributor_id, actor_id, actor_role, action, entity_type, entity_id, metadata
  ) VALUES (
    p_contributor_id,
    v_admin_id,
    'admin',
    'contributor_slug_override',
    'profiles',
    p_contributor_id::text,
    jsonb_build_object(
      'old_slug',     v_old_slug,
      'new_slug',     v_new_slug,
      'reason',       coalesce(p_reason, ''),
      'on_behalf_of', p_contributor_id
    )
  );

  RETURN v_new_slug;
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'slug_taken' USING ERRCODE = '23505';
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_create_contributor_profile(_target_id uuid, _display_name text, _claim_email text, _contributor_kind text, _contributor_category text, _bio text, _website_url text, _instagram_handle text, _facebook_url text, _tiktok_handle text, _youtube_url text, _no_fixed_location boolean, _physical_address text, _physical_latitude double precision, _physical_longitude double precision, _logo_url text, _gallery_urls jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  new_slug text;
begin
  if not public.is_admin() then
    return jsonb_build_object('success', false, 'reason', 'not_admin');
  end if;

  new_slug := public.generate_contributor_slug(coalesce(nullif(_display_name, ''), 'contributor'));

  update public.profiles set
    role = 'contributor',
    contributor_status = 'approved',
    contributor_kind = _contributor_kind,
    contributor_category = _contributor_category,
    full_name = coalesce(nullif(_display_name, ''), full_name),
    bio = _bio,
    website_url = _website_url,
    instagram_handle = _instagram_handle,
    facebook_url = _facebook_url,
    tiktok_handle = _tiktok_handle,
    youtube_url = _youtube_url,
    contributor_no_fixed_location = _no_fixed_location,
    physical_address = _physical_address,
    physical_latitude = _physical_latitude,
    physical_longitude = _physical_longitude,
    logo_url = _logo_url,
    gallery_urls = coalesce(_gallery_urls, '[]'::jsonb),
    contributor_slug = new_slug,
    contributor_claim_email = _claim_email,
    contributor_created_by_admin = auth.uid()
  where id = _target_id;

  if not found then
    return jsonb_build_object('success', false, 'reason', 'target_not_found');
  end if;

  return jsonb_build_object('success', true, 'slug', new_slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_citizens(_q text DEFAULT NULL::text, _signed_in text DEFAULT 'any'::text, _joined text DEFAULT 'any'::text, _application text DEFAULT 'any'::text, _page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_page integer;
  v_size constant integer := 20;
  v_q text;
  v_total integer;
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'not_admin' using errcode = '42501';
  end if;

  -- An explicit null is the same as omitting the argument (the default is 'any').
  _signed_in := coalesce(_signed_in, 'any');
  _joined := coalesce(_joined, 'any');
  _application := coalesce(_application, 'any');

  if _signed_in not in ('any', 'once', 'never')
     or _joined not in ('any', '7d', '30d', 'older')
     or _application not in ('any', 'pending', 'rejected', 'none') then
    return jsonb_build_object('success', false, 'reason', 'bad_filter');
  end if;

  v_page := least(greatest(coalesce(_page, 1), 1), 500);
  v_q := left(btrim(coalesce(_q, '')), 80);
  if v_q = '' then
    v_q := null;
  else
    v_q := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_');
  end if;

  select count(*) into v_total
    from public.profiles p
    join auth.users u on u.id = p.id
   where p.role = 'citizen'
     and p.deleted_at is null
     and (
       v_q is null
       or p.full_name ilike ('%' || v_q || '%') escape '\'
       or p.email ilike ('%' || v_q || '%') escape '\'
       or u.email ilike ('%' || v_q || '%') escape '\'
     )
     and (
       _signed_in = 'any'
       or (_signed_in = 'once' and u.last_sign_in_at is not null)
       or (_signed_in = 'never' and u.last_sign_in_at is null)
     )
     and (
       _joined = 'any'
       or (_joined = '7d' and p.created_at >= pg_catalog.now() - interval '7 days')
       or (_joined = '30d' and p.created_at >= pg_catalog.now() - interval '30 days')
       or (_joined = 'older' and p.created_at < pg_catalog.now() - interval '30 days')
     )
     and (
       _application = 'any'
       or (_application = 'pending' and p.contributor_status = 'pending')
       or (_application = 'rejected' and p.contributor_status = 'rejected')
       or (_application = 'none' and coalesce(p.contributor_status, 'not_applied') = 'not_applied')
     );

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'full_name', s.full_name,
           'avatar_url', s.avatar_url,
           'contributor_status', s.contributor_status,
           'created_at', s.created_at,
           'last_sign_in_at', s.last_sign_in_at
         ) order by s.created_at desc, s.id desc), '[]'::jsonb)
    into v_rows
    from (
      select p.id, p.full_name, p.avatar_url, p.contributor_status, p.created_at, u.last_sign_in_at
        from public.profiles p
        join auth.users u on u.id = p.id
       where p.role = 'citizen'
         and p.deleted_at is null
         and (
           v_q is null
           or p.full_name ilike ('%' || v_q || '%') escape '\'
           or p.email ilike ('%' || v_q || '%') escape '\'
           or u.email ilike ('%' || v_q || '%') escape '\'
         )
         and (
           _signed_in = 'any'
           or (_signed_in = 'once' and u.last_sign_in_at is not null)
           or (_signed_in = 'never' and u.last_sign_in_at is null)
         )
         and (
           _joined = 'any'
           or (_joined = '7d' and p.created_at >= pg_catalog.now() - interval '7 days')
           or (_joined = '30d' and p.created_at >= pg_catalog.now() - interval '30 days')
           or (_joined = 'older' and p.created_at < pg_catalog.now() - interval '30 days')
         )
         and (
           _application = 'any'
           or (_application = 'pending' and p.contributor_status = 'pending')
           or (_application = 'rejected' and p.contributor_status = 'rejected')
           or (_application = 'none' and coalesce(p.contributor_status, 'not_applied') = 'not_applied')
         )
       order by p.created_at desc, p.id desc
       offset (v_page - 1) * v_size
       limit v_size
    ) s;

  return jsonb_build_object(
    'success', true,
    'data', v_rows,
    'page', v_page,
    'page_size', v_size,
    'total', v_total
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.aggregate_contributor_analytics_daily(p_target_date date DEFAULT ((CURRENT_DATE - '1 day'::interval))::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows_written integer := 0;
BEGIN
  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'views',
    COUNT(v.id)::bigint
  FROM events e
  LEFT JOIN event_views v
    ON v.event_id = e.id
   AND v.viewed_at >= p_target_date
   AND v.viewed_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  HAVING COUNT(v.id) > 0
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();
  GET DIAGNOSTICS v_rows_written = ROW_COUNT;

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'rsvps',
    COUNT(r.id)::bigint
  FROM events e
  JOIN rsvps r
    ON r.event_id = e.id
   AND r.status = 'attending'
   AND r.created_at >= p_target_date
   AND r.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'cancellations',
    COUNT(rc.id)::bigint
  FROM events e
  JOIN rsvp_cancellations rc
    ON rc.event_id = e.id
   AND rc.cancelled_at >= p_target_date
   AND rc.cancelled_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'shares',
    COUNT(s.id)::bigint
  FROM events e
  JOIN shares s
    ON s.entity_type = 'event'
   AND s.entity_id = e.id
   AND s.created_at >= p_target_date
   AND s.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'joins',
    COUNT(cj.id)::bigint
  FROM events e
  JOIN rsvps r          ON r.event_id = e.id
  JOIN consider_joins cj ON cj.rsvp_id = r.id
   AND cj.created_at >= p_target_date
   AND cj.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'comments',
    COUNT(c.id)::bigint
  FROM events e
  JOIN comments c
    ON c.event_id = e.id
   AND c.created_at >= p_target_date
   AND c.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'convinces',
    COUNT(cv.id)::bigint
  FROM events e
  JOIN convinces cv
    ON cv.event_id = e.id
   AND cv.created_at >= p_target_date
   AND cv.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    e.created_by, 'event', e.id, p_target_date, 'reports',
    COUNT(rp.id)::bigint
  FROM events e
  JOIN reports rp
    ON rp.target_type = 'event'
   AND rp.target_id = e.id
   AND rp.created_at >= p_target_date
   AND rp.created_at <  p_target_date + INTERVAL '1 day'
  WHERE e.created_by IS NOT NULL
  GROUP BY e.created_by, e.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    bm.contributor_id, 'event', bm.entity_id, p_target_date, 'broadcasts',
    COUNT(bm.id)::bigint
  FROM broadcast_messages bm
  WHERE bm.entity_type = 'event'
    AND bm.deleted_at IS NULL
    AND bm.created_at >= p_target_date
    AND bm.created_at <  p_target_date + INTERVAL '1 day'
  GROUP BY bm.contributor_id, bm.entity_id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    p.created_by, 'place', p.id, p_target_date, 'follows',
    COUNT(pf.id)::bigint
  FROM places p
  JOIN place_follows pf
    ON pf.place_id = p.id
   AND pf.created_at >= p_target_date
   AND pf.created_at <  p_target_date + INTERVAL '1 day'
  WHERE p.created_by IS NOT NULL
  GROUP BY p.created_by, p.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    p.created_by, 'place', p.id, p_target_date, 'shares',
    COUNT(s.id)::bigint
  FROM places p
  JOIN shares s
    ON s.entity_type = 'place'
   AND s.entity_id = p.id
   AND s.created_at >= p_target_date
   AND s.created_at <  p_target_date + INTERVAL '1 day'
  WHERE p.created_by IS NOT NULL
  GROUP BY p.created_by, p.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    p.created_by, 'place', p.id, p_target_date, 'reports',
    COUNT(rp.id)::bigint
  FROM places p
  JOIN reports rp
    ON rp.target_type = 'place'
   AND rp.target_id = p.id
   AND rp.created_at >= p_target_date
   AND rp.created_at <  p_target_date + INTERVAL '1 day'
  WHERE p.created_by IS NOT NULL
  GROUP BY p.created_by, p.id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    bm.contributor_id, 'place', bm.entity_id, p_target_date, 'broadcasts',
    COUNT(bm.id)::bigint
  FROM broadcast_messages bm
  WHERE bm.entity_type = 'place'
    AND bm.deleted_at IS NULL
    AND bm.created_at >= p_target_date
    AND bm.created_at <  p_target_date + INTERVAL '1 day'
  GROUP BY bm.contributor_id, bm.entity_id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    f.followee_id, 'contributor', NULL, p_target_date, 'follows',
    COUNT(*)::bigint
  FROM follows f
  WHERE f.created_at >= p_target_date
    AND f.created_at <  p_target_date + INTERVAL '1 day'
  GROUP BY f.followee_id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    s.entity_id, 'contributor', NULL, p_target_date, 'shares',
    COUNT(*)::bigint
  FROM shares s
  WHERE s.entity_type = 'contributor'
    AND s.created_at >= p_target_date
    AND s.created_at <  p_target_date + INTERVAL '1 day'
  GROUP BY s.entity_id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  SELECT
    rp.target_id, 'contributor', NULL, p_target_date, 'reports',
    COUNT(*)::bigint
  FROM reports rp
  WHERE rp.target_type = 'user'
    AND rp.created_at >= p_target_date
    AND rp.created_at <  p_target_date + INTERVAL '1 day'
  GROUP BY rp.target_id
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
    DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  RETURN v_rows_written;
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_admin_elevation(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_request  public.pending_admin_elevations%rowtype;
  v_approver uuid := auth.uid();
  v_admin_count int;
begin
  if v_approver is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not public.is_admin() then
    raise exception 'Admin role required' using errcode = '42501';
  end if;

  select * into v_request
    from public.pending_admin_elevations
   where id = p_request_id
   for update;

  if not found then
    raise exception 'Elevation request not found' using errcode = 'P0002';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'Elevation request is not pending (status = %)', v_request.status
      using errcode = 'P0001';
  end if;

  if v_request.expires_at < now() then
    update public.pending_admin_elevations
       set status = 'expired'
     where id = p_request_id;
    raise exception 'Elevation request has expired' using errcode = 'P0001';
  end if;

  if v_request.requested_by = v_approver then
    select count(*) into v_admin_count from public.profiles where role = 'admin';

    if v_admin_count > 1 then
      raise exception 'A different admin must approve this elevation request'
        using errcode = 'P0001';
    end if;

    if now() < v_request.requested_at + interval '24 hours' then
      raise exception 'Solo-admin self-approval requires a 24-hour waiting period. Please try again after %',
        (v_request.requested_at + interval '24 hours')
        using errcode = 'P0001';
    end if;
  end if;

  update public.profiles
     set role = 'admin'
   where id = v_request.target_user_id;

  update public.pending_admin_elevations
     set status = 'approved',
         approved_by = v_approver,
         approved_at = now()
   where id = p_request_id;

  return p_request_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_dashboard_access(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contributor_id uuid;
BEGIN
  SELECT contributor_id INTO v_contributor_id
  FROM contributor_access_requests
  WHERE id = p_request_id AND status = 'pending';

  IF v_contributor_id IS NULL THEN
    RAISE EXCEPTION 'request_not_found';
  END IF;

  PERFORM check_max_dashboard_sessions(v_contributor_id);

  UPDATE contributor_access_requests
  SET status = 'approved',
      expires_at = now() + interval '3 days',
      updated_at = now()
  WHERE id = p_request_id;

  INSERT INTO activity_log (contributor_id, actor_id, action, entity_type, entity_id, metadata)
  SELECT v_contributor_id, auth.uid(), 'dashboard_access_approved',
         'access_request', p_request_id::text,
         jsonb_build_object('admin_id', admin_id)
  FROM contributor_access_requests
  WHERE id = p_request_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.backfill_contributor_analytics(p_days_back integer DEFAULT 90)
 RETURNS TABLE(target_date date, rows_written integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_date date;
  v_rows        integer;
BEGIN
  IF p_days_back IS NULL OR p_days_back < 1 THEN
    p_days_back := 90;
  ELSIF p_days_back > 365 THEN
    p_days_back := 365;
  END IF;

  FOR i IN 1 .. p_days_back LOOP
    v_target_date := (CURRENT_DATE - i)::date;

    v_rows := public.aggregate_contributor_analytics_daily(v_target_date);

    target_date  := v_target_date;
    rows_written := v_rows;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$function$;

CREATE OR REPLACE FUNCTION public.bump_tag_usage_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if TG_OP = 'INSERT' then
    update public.event_tags
       set usage_count = usage_count + 1
     where id = new.tag_id;
    return new;
  elsif TG_OP = 'DELETE' then
    update public.event_tags
       set usage_count = greatest(0, usage_count - 1)
     where id = old.tag_id;
    return old;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.caller_may_read_private_event(p_event uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null
     and p_event is not null
     and (
       exists (
         select 1
         from public.events e
         where e.id = p_event
           and e.created_by = (select auth.uid())
       )
       or (select public.is_admin())
       or exists (
         select 1
         from public.rsvps r
         where r.event_id = p_event
           and r.user_id = (select auth.uid())
       )
       or exists (
         select 1
         from public.event_cohosts c
         where c.event_id = p_event
           and c.contributor_id = (select auth.uid())
           and c.status in ('invited', 'accepted')
       )
     );
$function$;

CREATE OR REPLACE FUNCTION public.check_max_dashboard_sessions(p_contributor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  active_count integer;
BEGIN
  SELECT COUNT(*) INTO active_count
  FROM contributor_access_requests
  WHERE contributor_id = p_contributor_id
    AND status = 'approved'
    AND (expires_at IS NULL OR expires_at > now())
    AND revoked_at IS NULL;

  IF active_count >= 2 THEN
    RAISE EXCEPTION 'max_sessions_reached'
      USING HINT = 'A maximum of 2 admin sessions may be active at once.';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.claim_admin_created_contributor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_email text;
  caller_confirmed timestamptz;
  caller_role text;
  caller_status text;
  ledger record;
  placeholder record;
  new_slug text;
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason', 'not_authenticated');
  end if;

  select email, email_confirmed_at into caller_email, caller_confirmed
    from auth.users where id = auth.uid();
  if caller_email is null or caller_email = '' then
    return jsonb_build_object('success', false, 'reason', 'no_email');
  end if;
  if caller_confirmed is null then
    return jsonb_build_object('success', false, 'reason', 'email_not_verified');
  end if;

  select role, contributor_status into caller_role, caller_status
    from public.profiles where id = auth.uid();
  if caller_role is distinct from 'citizen' or caller_status is distinct from 'not_applied' then
    return jsonb_build_object('success', false, 'reason', 'not_eligible');
  end if;

  select lc.* into ledger from public.listing_claims lc
   where lc.status = 'awaiting'
     and lc.claim_email = lower(btrim(caller_email))
     and lc.placeholder_id <> auth.uid()
   for update;
  if not found then
    return jsonb_build_object('success', false, 'reason', 'nothing_to_claim');
  end if;

  select * into placeholder from public.profiles
   where id = ledger.placeholder_id
     and role = 'contributor' and contributor_status = 'approved'
     and coalesce(contributor_hidden, false) = false and deleted_at is null
   for update;
  if not found then
    return jsonb_build_object('success', false, 'reason', 'nothing_to_claim');
  end if;

  update public.profiles set
    contributor_hidden = true,
    contributor_slug = null,
    contributor_claim_email = null,
    contributor_claimed_at = now()
  where id = placeholder.id;

  new_slug := coalesce(
    placeholder.contributor_slug,
    public.generate_contributor_slug(coalesce(nullif(placeholder.full_name, ''), 'contributor'))
  );

  update public.profiles set contributor_status = 'pending' where id = auth.uid();

  update public.profiles set
    role = 'contributor',
    contributor_status = 'approved',
    contributor_hidden = false,
    contributor_kind = placeholder.contributor_kind,
    contributor_category = placeholder.contributor_category,
    full_name = coalesce(nullif(placeholder.full_name, ''), full_name),
    bio = coalesce(placeholder.bio, bio),
    website_url = coalesce(placeholder.website_url, website_url),
    contributor_contact_email = coalesce(placeholder.contributor_contact_email, contributor_contact_email),
    instagram_handle = coalesce(placeholder.instagram_handle, instagram_handle),
    facebook_url = coalesce(placeholder.facebook_url, facebook_url),
    tiktok_handle = coalesce(placeholder.tiktok_handle, tiktok_handle),
    youtube_url = coalesce(placeholder.youtube_url, youtube_url),
    x_handle = coalesce(placeholder.x_handle, x_handle),
    linkedin_url = coalesce(placeholder.linkedin_url, linkedin_url),
    whatsapp_number = coalesce(placeholder.whatsapp_number, whatsapp_number),
    contributor_no_fixed_location = placeholder.contributor_no_fixed_location,
    physical_address = placeholder.physical_address,
    physical_latitude = placeholder.physical_latitude,
    physical_longitude = placeholder.physical_longitude,
    logo_url = coalesce(placeholder.logo_url, logo_url),
    gallery_urls = case
      when jsonb_array_length(coalesce(placeholder.gallery_urls, '[]'::jsonb)) > 0
        then placeholder.gallery_urls
      else gallery_urls
    end,
    cover_photo_urls = case
      when jsonb_array_length(coalesce(placeholder.cover_photo_urls, '[]'::jsonb)) > 0
        then placeholder.cover_photo_urls
      else cover_photo_urls
    end,
    contributor_slug = new_slug,
    needs_re_review = false
  where id = auth.uid();

  update public.listing_claims set
    status = 'confirmed', claimant_id = auth.uid(), decided_at = now()
  where id = ledger.id;

  return jsonb_build_object('success', true, 'slug', new_slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.cleanup_stale_locations()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.user_locations ul
  where not exists (
    select 1 from public.events e
    where e.id = ul.event_id
      and (
        (e.end_time is not null and e.end_time::timestamptz > now() - interval '30 minutes')
        or
        (e.end_time is null and e.date::timestamptz + interval '4 hours' > now() - interval '30 minutes')
      )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.count_friends(target_user uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select count(*)
  from public.follows f1
  join public.follows f2
    on f1.followee_id = f2.follower_id
   and f1.follower_id = f2.followee_id
  where f1.follower_id = target_user;
$function$;

CREATE OR REPLACE FUNCTION public.decline_listing_claim()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_email text;
  caller_confirmed timestamptz;
  ledger record;
  listing_name text;
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason', 'not_authenticated');
  end if;

  select email, email_confirmed_at into caller_email, caller_confirmed
    from auth.users where id = auth.uid();
  if caller_email is null or caller_email = '' or caller_confirmed is null then
    return jsonb_build_object('success', false, 'reason', 'email_not_verified');
  end if;

  select lc.* into ledger from public.listing_claims lc
   where lc.status = 'awaiting'
     and lc.claim_email = lower(btrim(caller_email))
   for update;
  if not found then
    return jsonb_build_object('success', false, 'reason', 'nothing_to_decline');
  end if;

  update public.profiles set contributor_hidden = true
   where id = ledger.placeholder_id
  returning full_name into listing_name;

  update public.listing_claims set status = 'declined', decided_at = now()
   where id = ledger.id;

  return jsonb_build_object('success', true, 'name', listing_name, 'slug', ledger.slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_contributor_application(_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  app record;
begin
  if not public.is_admin() then
    return jsonb_build_object('success', false, 'reason', 'not_admin');
  end if;

  select id, user_id, status into app
  from public.contributor_applications
  where id = _application_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'reason', 'not_found');
  end if;

  if app.status = 'pending' then
    update public.profiles
      set contributor_status = 'not_applied'
      where id = app.user_id
        and contributor_status = 'pending';
  end if;

  delete from public.contributor_applications where id = _application_id;

  return jsonb_build_object(
    'success', true,
    'action', 'deleted',
    'user_id', app.user_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.deny_dashboard_access(p_request_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contributor_id uuid;
BEGIN
  IF char_length(p_reason) < 3 OR char_length(p_reason) > 500 THEN
    RAISE EXCEPTION 'invalid_reason';
  END IF;

  UPDATE contributor_access_requests
  SET status = 'denied',
      denial_reason = p_reason,
      updated_at = now()
  WHERE id = p_request_id
    AND status = 'pending'
  RETURNING contributor_id INTO v_contributor_id;

  IF v_contributor_id IS NULL THEN
    RAISE EXCEPTION 'request_not_found';
  END IF;

  INSERT INTO activity_log (contributor_id, actor_id, action, entity_type, entity_id, metadata)
  SELECT v_contributor_id, auth.uid(), 'dashboard_access_denied',
         'access_request', p_request_id::text,
         jsonb_build_object('reason', p_reason)
  FROM contributor_access_requests
  WHERE id = p_request_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.dismiss_map_bubble(p_bubble_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_bubble_id is null then
    raise exception 'invalid_arguments' using errcode = '22023';
  end if;

  insert into public.bubble_dismissals (bubble_id, user_id)
  values (p_bubble_id, v_uid)
  on conflict (bubble_id, user_id) do nothing;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_at_least_one_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  remaining int;
begin
  if tg_op = 'UPDATE' then
    if old.role = 'admin' and (new.role is distinct from 'admin') then
      select count(*) into remaining
      from public.profiles
      where role = 'admin' and id <> old.id;
      if remaining = 0 then
        raise exception 'Cannot remove the last admin.'
          using errcode = 'P0001';
      end if;
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    if old.role = 'admin' then
      select count(*) into remaining
      from public.profiles
      where role = 'admin' and id <> old.id;
      if remaining = 0 then
        raise exception 'Cannot remove the last admin.'
          using errcode = 'P0001';
      end if;
    end if;
    return old;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_place_six_month_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if public.is_admin() then
    return old;
  end if;

  if old.created_at > (now() - interval '6 months') then
    raise exception 'places cannot be removed within 6 months of creation'
      using errcode = '42501';
  end if;

  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_tag_cap_per_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _count int;
begin
  select count(*) into _count
    from public.event_tag_assignments
   where event_id = new.event_id;
  if _count >= 5 then
    raise exception 'event_tag_cap_reached: an event can have at most 5 tags'
      using errcode = 'P0001';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_contributor_self_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_other_owner_exists boolean;
BEGIN
  IF NEW.contributor_status = 'approved'
     AND (TG_OP = 'INSERT' OR OLD.contributor_status IS DISTINCT FROM 'approved')
  THEN
    SELECT EXISTS (
      SELECT 1 FROM team_memberships
      WHERE contributor_id = NEW.id
        AND member_id     <> NEW.id
        AND role           = 'owner'
        AND status         = 'active'
    ) INTO v_other_owner_exists;

    IF v_other_owner_exists THEN
      RETURN NEW;
    END IF;

    INSERT INTO team_memberships
      (contributor_id, member_id, role, status, invited_by)
    VALUES
      (NEW.id, NEW.id, 'owner', 'active', NEW.id)
    ON CONFLICT (contributor_id, member_id)
    DO UPDATE SET
      role       = 'owner',
      status     = 'active',
      updated_at = now()
    WHERE team_memberships.role <> 'owner'
       OR team_memberships.status <> 'active';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.events_set_community_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _role text;
begin
  if TG_OP <> 'INSERT' then
    return new;
  end if;
  select role into _role from public.profiles where id = new.created_by;
  if _role = 'citizen' then
    new.community_contributor := true;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.find_conversation(user_a uuid, user_b uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT cp1.conversation_id
  FROM public.conversation_participants cp1
  JOIN public.conversation_participants cp2 ON cp1.conversation_id = cp2.conversation_id
  WHERE cp1.user_id = user_a AND cp2.user_id = user_b
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.find_or_create_conversation(user_a uuid, user_b uuid, p_status text DEFAULT 'active'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  conv_id uuid;
begin
  if auth.uid() is null or (auth.uid() <> user_a and auth.uid() <> user_b) then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  if user_a = user_b then
    raise exception 'Cannot create conversation with yourself';
  end if;

  if p_status not in ('pending', 'active') then
    raise exception 'Invalid status: %', p_status;
  end if;

  select cp1.conversation_id into conv_id
  from public.conversation_participants cp1
  join public.conversation_participants cp2
    on cp1.conversation_id = cp2.conversation_id
  where cp1.user_id = user_a and cp2.user_id = user_b
  limit 1;

  if conv_id is not null then
    return conv_id;
  end if;

  insert into public.conversations (status) values (p_status) returning id into conv_id;
  insert into public.conversation_participants (conversation_id, user_id)
  values (conv_id, user_a), (conv_id, user_b);

  return conv_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.followed_post_audience(p_contributor uuid, p_kind text, p_post_id uuid)
 RETURNS TABLE(follower_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select f.follower_id
  from public.follows f
  join public.profiles fp on fp.id = f.follower_id
  where f.followee_id = p_contributor
    and f.follower_id <> p_contributor
    and coalesce((fp.notification_prefs->>'contributor_updates')::boolean, true) = true
    and not (coalesce(fp.muted_source_ids, '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('type', 'org', 'id', p_contributor::text)))
    and not (p_kind = 'followed_new_event' and coalesce(fp.muted_source_ids, '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('type', 'event', 'id', p_post_id::text)))
    and not exists (
      select 1 from public.user_blocks b
      where (b.blocker_id = f.follower_id and b.blocked_id = p_contributor)
         or (b.blocker_id = p_contributor and b.blocked_id = f.follower_id)
    )
    and not exists (
      select 1 from public.notifications n
      where n.user_id = f.follower_id and n.type = p_kind
        and (n.data->>'post_id') = p_post_id::text
    )
    and (
      select count(*) from public.notifications n
      where n.user_id = f.follower_id and n.type in ('followed_new_event', 'followed_new_news')
        and (n.data->>'contributor_id') = p_contributor::text
        and n.created_at > now() - interval '24 hours'
    ) < 2
  order by f.created_at desc
  limit 500;
$function$;

CREATE OR REPLACE FUNCTION public.follower_count_exact(p_followee uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select count(*)::bigint from public.follows where followee_id = p_followee;
$function$;

CREATE OR REPLACE FUNCTION public.follower_count_public(p_followee uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with n as (select count(*)::bigint as c from public.follows where followee_id = p_followee)
  select case
    when n.c < 100 then 0::bigint
    else (select max(s) from unnest(array[100, 250, 500, 1000, 2500, 5000, 10000, 25000, 50000, 100000]::bigint[]) as s where s <= n.c)
  end
  from n;
$function$;

CREATE OR REPLACE FUNCTION public.friends_considering_event(p_event uuid)
 RETURNS TABLE(id uuid, full_name text, avatar_url text, nudged boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select p.id,
         p.full_name,
         p.avatar_url,
         exists (
           select 1 from public.convinces c
           where c.from_user_id = auth.uid() and c.to_user_id = p.id and c.event_id = p_event
         ) as nudged
    from public.rsvps r
    join public.profiles p on p.id = r.user_id
   where auth.uid() is not null
     and p_event is not null
     and r.event_id = p_event
     and r.status = 'considering'
     and exists (select 1 from public.follows f where f.follower_id = auth.uid() and f.followee_id = r.user_id)
     and public.is_considering_for_friend(r.user_id, p_event)
   order by lower(p.full_name), p.id
   limit 50;
$function$;

CREATE OR REPLACE FUNCTION public.generate_contributor_slug(_name text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare base_slug text; candidate text; counter int := 1;
begin
  base_slug := regexp_replace(lower(coalesce(_name, '')), '[^a-z0-9]+', '-', 'g');
  base_slug := regexp_replace(base_slug, '(^-+|-+$)', '', 'g');
  if base_slug = '' or base_slug is null then base_slug := 'contributor'; end if;
  candidate := base_slug;
  while exists (select 1 from public.profiles where contributor_slug = candidate) loop
    counter := counter + 1;
    candidate := base_slug || '-' || counter::text;
  end loop;
  return candidate;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_active_map_bubbles()
 RETURNS TABLE(id uuid, event_id uuid, body text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select b.id, b.event_id, b.body, b.created_at
  from public.map_bubbles b
  where b.expires_at > now()
    and exists (
      select 1
      from public.events e
      where e.id = b.event_id
        and (
          (e.visibility = 'public' and e.status in ('published', 'cancelled'))
          or e.created_by = (select auth.uid())
          or (select public.is_admin())
          or (
            e.visibility = 'private'
            and e.status in ('published', 'cancelled')
            and public.caller_may_read_private_event(e.id)
          )
        )
    )
    and not exists (
      select 1
      from public.bubble_dismissals d
      where d.bubble_id = b.id
        and d.user_id = (select auth.uid())
    );
$function$;

CREATE OR REPLACE FUNCTION public.get_category_trends()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb;
begin
  if not public.is_admin() then raise exception 'Not authorised' using errcode = '42501'; end if;
  with current_window as (
    select category, count(*)::int as c from public.events
    where category is not null and date >= now() - interval '30 days' and date < now() and status = 'published' group by 1
  ),
  prior_window as (
    select category, count(*)::int as c from public.events
    where category is not null and date >= now() - interval '60 days' and date < now() - interval '30 days' and status = 'published' group by 1
  ),
  all_categories as (
    select category from current_window union select category from prior_window
  )
  select jsonb_agg(
    jsonb_build_object(
      'category', ac.category,
      'current_30d', coalesce(cw.c, 0),
      'prior_30d', coalesce(pw.c, 0),
      'growth_pct', case when coalesce(pw.c, 0) = 0 then null else round(((coalesce(cw.c, 0) - pw.c)::numeric / pw.c) * 100, 1) end
    ) order by coalesce(cw.c, 0) desc
  ) into v_result
  from all_categories ac
  left join current_window cw on cw.category = ac.category
  left join prior_window pw on pw.category = ac.category;
  return coalesce(v_result, '[]'::jsonb);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_community_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb;
begin
  if not public.is_admin() then raise exception 'Not authorised' using errcode = '42501'; end if;
  select jsonb_build_object(
    'active_contributors', (select count(*) from public.profiles where role = 'contributor' and contributor_status = 'approved'),
    'new_contributors_30d', (select count(*) from public.profiles where role = 'contributor' and contributor_status = 'approved' and created_at >= now() - interval '30 days'),
    'events_30d', (select count(*) from public.events where status = 'published' and created_at >= now() - interval '30 days'),
    'rsvps_30d', (select count(*) from public.rsvps where created_at >= now() - interval '30 days'),
    'unique_rsvpers_30d', (select count(distinct user_id) from public.rsvps where created_at >= now() - interval '30 days'),
    'total_citizens', (select count(*) from public.profiles where role = 'citizen'),
    'total_events_all_time', (select count(*) from public.events where status = 'published')
  ) into v_result;
  return v_result;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_community_ideas()
 RETURNS TABLE(id uuid, title text, body text, category text, tier text, tier_label text, vote_threshold integer, idea_status text, project_lead_id uuid, associated_event_id uuid, latitude double precision, longitude double precision, created_at timestamp with time zone, author_name text, author_avatar text, vote_count bigint, voted_by_me boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select s.id, s.title, s.body, s.category,
         s.tier, s.tier_label, s.vote_threshold, s.idea_status,
         s.project_lead_id, s.associated_event_id,
         s.latitude, s.longitude, s.created_at,
         p.full_name  as author_name,
         p.avatar_url as author_avatar,
         (select count(*) from public.idea_votes v where v.idea_id = s.id) as vote_count,
         (auth.uid() is not null and exists (
            select 1 from public.idea_votes v
             where v.idea_id = s.id and v.user_id = auth.uid())) as voted_by_me
    from public.suggestions s
    left join public.profiles p on p.id = s.user_id
   where s.page_url ilike '%/community'
     and s.status in ('open','in_review','actioned')
   order by s.created_at desc
   limit 200;
$function$;

CREATE OR REPLACE FUNCTION public.get_contributor_public_stats(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_status text;
  v_hidden boolean;
  v_deleted timestamptz;
begin
  if p_org_id is null then
    return null;
  end if;

  select p.role, p.contributor_status, p.contributor_hidden, p.deleted_at
    into v_role, v_status, v_hidden, v_deleted
  from public.profiles p
  where p.id = p_org_id;

  if v_role is distinct from 'contributor'
     or v_status is distinct from 'approved'
     or coalesce(v_hidden, false)
     or v_deleted is not null then
    return null;
  end if;

  return jsonb_build_object(
    'total_events', (
      select count(*) from public.events
      where created_by = p_org_id
        and status = 'published' and visibility = 'public'
    ),
    'upcoming_events', (
      select count(*) from public.events
      where created_by = p_org_id
        and status = 'published' and visibility = 'public'
        and date >= now()
    ),
    'total_rsvps', (
      select count(*) from public.rsvps r
      join public.events e on e.id = r.event_id
      where e.created_by = p_org_id
        and e.status = 'published' and e.visibility = 'public'
    ),
    'followers', public.follower_count_public(p_org_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_mutual_followers(p_user_a uuid, p_user_b uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, full_name text, avatar_url text, role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or (auth.uid() <> p_user_a and auth.uid() <> p_user_b) then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  return query
    select p.id, p.full_name, p.avatar_url, p.role
    from public.profiles p
    where p.id in (
      select f1.followee_id
      from public.follows f1
      where f1.follower_id = p_user_a
      intersect
      select f2.followee_id
      from public.follows f2
      where f2.follower_id = p_user_b
    )
    order by p.full_name nulls last
    limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_org_audience(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rsvps jsonb; v_followers jsonb;
begin
  if auth.uid() is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if auth.uid() <> p_org_id and not public.is_admin() then
    raise exception 'Not authorised to view this org' using errcode = '42501';
  end if;
  with days as (
    select (current_date - (n || ' days')::interval)::date as day from generate_series(0, 29) n
  ),
  rsvp_counts as (
    select date_trunc('day', r.created_at)::date as day, count(*)::int as c
    from public.rsvps r join public.events e on e.id = r.event_id
    where e.created_by = p_org_id and r.created_at >= current_date - interval '30 days' group by 1
  ),
  follower_counts as (
    select date_trunc('day', created_at)::date as day, count(*)::int as c
    from public.follows where followee_id = p_org_id and created_at >= current_date - interval '30 days' group by 1
  )
  select
    jsonb_agg(jsonb_build_object('day', d.day, 'count', coalesce(r.c, 0)) order by d.day),
    jsonb_agg(jsonb_build_object('day', d.day, 'count', coalesce(f.c, 0)) order by d.day)
  into v_rsvps, v_followers
  from days d left join rsvp_counts r on r.day = d.day left join follower_counts f on f.day = d.day;
  return jsonb_build_object(
    'rsvps_30d', coalesce(v_rsvps, '[]'::jsonb),
    'new_followers_30d', coalesce(v_followers, '[]'::jsonb)
  );
end; $function$;

CREATE OR REPLACE FUNCTION public.get_org_event_stats(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb; v_total_events int; v_upcoming int; v_past int;
  v_total_rsvps int; v_views_total int; v_new_followers_30d int; v_avg_rsvps numeric;
begin
  if auth.uid() is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if auth.uid() <> p_org_id and not public.is_admin() then
    raise exception 'Not authorised to view this org' using errcode = '42501';
  end if;
  select count(*) into v_total_events from public.events where created_by = p_org_id and status = 'published';
  select count(*) into v_upcoming from public.events where created_by = p_org_id and status = 'published' and date >= now();
  select count(*) into v_past from public.events where created_by = p_org_id and status = 'published' and date < now();
  select count(*) into v_total_rsvps from public.rsvps r join public.events e on e.id = r.event_id where e.created_by = p_org_id;
  select count(*) into v_views_total from public.event_views v join public.events e on e.id = v.event_id where e.created_by = p_org_id;
  select count(*) into v_new_followers_30d from public.follows where followee_id = p_org_id and created_at >= now() - interval '30 days';
  v_avg_rsvps := case when v_total_events = 0 then 0 else round(v_total_rsvps::numeric / v_total_events, 2) end;
  v_result := jsonb_build_object(
    'total_events', v_total_events, 'upcoming', v_upcoming, 'past', v_past,
    'total_rsvps', v_total_rsvps, 'avg_rsvps_per_event', v_avg_rsvps,
    'views_total', v_views_total, 'new_followers_30d', v_new_followers_30d
  );
  return v_result;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_place_review_stats(p_window_start timestamp with time zone DEFAULT (now() - '1 year'::interval))
 RETURNS TABLE(place_id uuid, review_count bigint, total_rating numeric, negative_signals bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    r.place_id,
    count(*)::bigint                                                  as review_count,
    sum(r.rating)::numeric                                            as total_rating,
    count(*) filter (where r.still_exists = false)::bigint           as negative_signals
  from public.reviews r
  where r.place_id is not null
    and r.created_at >= p_window_start
  group by r.place_id
$function$;

CREATE OR REPLACE FUNCTION public.get_public_contributor_analytics(p_contributor_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(metric text, total bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_days IS NULL OR p_days < 1 THEN
    p_days := 30;
  ELSIF p_days > 365 THEN
    p_days := 365;
  END IF;

  RETURN QUERY
  SELECT
    ca.metric,
    SUM(ca.value)::bigint AS total
  FROM contributor_analytics ca
  WHERE ca.contributor_id = p_contributor_id
    AND ca.date >= (CURRENT_DATE - (p_days || ' days')::interval)::date
    AND ca.metric IN ('follows', 'joins')
  GROUP BY ca.metric;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_team(p_contributor_id uuid)
 RETURNS TABLE(member_id uuid, full_name text, avatar_url text, role text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    tm.member_id,
    p.full_name,
    p.avatar_url,
    tm.role
  FROM team_memberships tm
  JOIN profiles p ON p.id = tm.member_id
  WHERE tm.contributor_id = p_contributor_id
    AND tm.status = 'active'
  ORDER BY
    CASE tm.role WHEN 'owner' THEN 0 WHEN 'editor' THEN 1 ELSE 2 END,
    tm.created_at ASC
$function$;

CREATE OR REPLACE FUNCTION public.get_search_autocomplete(p_prefix text, p_limit integer DEFAULT 8)
 RETURNS TABLE(suggestion text, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prefix text := public.sanitise_search_term(p_prefix);
  v_like   text;
BEGIN
  IF v_prefix IS NULL THEN
    RETURN;
  END IF;
  IF p_limit IS NULL OR p_limit < 1 THEN p_limit := 8; END IF;
  IF p_limit > 20 THEN p_limit := 20; END IF;

  v_like := replace(replace(replace(v_prefix, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  RETURN QUERY
  WITH keyword_hits AS (
    SELECT DISTINCT lower(ck.keyword) AS suggestion, 'keyword'::text AS source, 0 AS rank
    FROM contributor_keywords ck
    WHERE lower(ck.keyword) LIKE v_like
    LIMIT 50
  ),
  term_hits AS (
    SELECT s.term AS suggestion, 'popular'::text AS source, 1 AS rank
    FROM search_term_stats s
    WHERE s.term LIKE v_like
      AND s.day >= (CURRENT_DATE - interval '30 days')::date
    GROUP BY s.term
    ORDER BY SUM(s.hits) DESC
    LIMIT 50
  ),
  merged AS (
    SELECT suggestion, source, rank FROM keyword_hits
    UNION ALL
    SELECT suggestion, source, rank FROM term_hits
  ),
  deduped AS (
    SELECT DISTINCT ON (suggestion) suggestion, source, rank
    FROM merged
    ORDER BY suggestion, rank
  )
  SELECT d.suggestion, d.source
  FROM deduped d
  ORDER BY d.rank, d.suggestion
  LIMIT p_limit;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_top_search_terms(p_limit integer DEFAULT 10, p_days integer DEFAULT 30)
 RETURNS TABLE(term text, hits bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_limit IS NULL OR p_limit < 1 THEN p_limit := 10; END IF;
  IF p_limit > 50 THEN p_limit := 50; END IF;
  IF p_days IS NULL OR p_days < 1 THEN p_days := 30; END IF;
  IF p_days > 180 THEN p_days := 180; END IF;

  RETURN QUERY
  SELECT s.term, SUM(s.hits)::bigint AS hits
  FROM search_term_stats s
  WHERE s.day >= (CURRENT_DATE - (p_days || ' days')::interval)::date
  GROUP BY s.term
  ORDER BY SUM(s.hits) DESC, s.term ASC
  LIMIT p_limit;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_open_to_collaborate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.open_to_collaborate is not distinct from old.open_to_collaborate then
    return new;
  end if;

  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if public.is_admin() then
    return new;
  end if;

  if auth.uid() is null
     or auth.uid() is distinct from old.id
     or old.role is distinct from 'contributor'
     or old.contributor_status is distinct from 'approved'
     or old.deleted_at is not null then
    raise exception 'open_to_collaborate is managed by the listing'
      using errcode = '42501';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.increment_broadcast_reaction(p_broadcast_id uuid, p_emoji text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_broadcast_id is null then
    raise exception 'invalid_arguments' using errcode = '22023';
  end if;
  if p_emoji not in ('🙏', '❤️', '🎉', '🙌', '🔥') then
    raise exception 'invalid_emoji' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.broadcast_messages
    where id = p_broadcast_id and deleted_at is null
  ) then
    raise exception 'broadcast_not_found' using errcode = 'P0002';
  end if;

  insert into public.broadcast_reactions (broadcast_id, emoji, count)
  values (p_broadcast_id, p_emoji, 1)
  on conflict (broadcast_id, emoji)
  do update set count = public.broadcast_reactions.count + 1
  returning count into v_count;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.increment_contributor_metric(p_contributor_id uuid, p_entity_type text, p_entity_id uuid, p_metric text, p_delta bigint DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO contributor_analytics
    (contributor_id, entity_type, entity_id, date, metric, value)
  VALUES
    (p_contributor_id, p_entity_type, p_entity_id, CURRENT_DATE, p_metric, p_delta)
  ON CONFLICT (contributor_id, entity_type, entity_id, date, metric)
  DO UPDATE SET value = contributor_analytics.value + EXCLUDED.value,
                updated_at = now();
END;
$function$;

CREATE OR REPLACE FUNCTION public.invite_event_cohost(p_event_id uuid, p_contributor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid  uuid := (select auth.uid());
  v_title text;
begin
  if v_uid is null then return jsonb_build_object('success', false, 'reason', 'not_authenticated'); end if;
  if p_contributor_id = v_uid then return jsonb_build_object('success', false, 'reason', 'cannot_cohost_self'); end if;

  select e.title into v_title from public.events e where e.id = p_event_id and e.created_by = v_uid;
  if not found then return jsonb_build_object('success', false, 'reason', 'not_event_owner'); end if;

  perform pg_advisory_xact_lock(hashtextextended(p_event_id::text, 0));

  if not exists (
    select 1 from public.profiles p
    where p.id = p_contributor_id and p.role = 'contributor' and p.contributor_status = 'approved'
      and coalesce(p.contributor_hidden, false) = false
  ) then return jsonb_build_object('success', false, 'reason', 'not_a_contributor'); end if;

  if public.is_blocked(v_uid, p_contributor_id) then return jsonb_build_object('success', false, 'reason', 'not_allowed'); end if;

  if (select count(*) from public.event_cohosts where event_id = p_event_id and status in ('invited', 'accepted')) >= 3 then
    return jsonb_build_object('success', false, 'reason', 'too_many_cohosts');
  end if;

  insert into public.event_cohosts (event_id, contributor_id, invited_by) values (p_event_id, p_contributor_id, v_uid)
  on conflict (event_id, contributor_id) do nothing;
  if not found then return jsonb_build_object('success', false, 'reason', 'already_invited'); end if;

  insert into public.notifications (user_id, type, title, body, data)
  values (p_contributor_id, 'cohost_invite', 'Co-host invitation',
          'You are invited to co-host: ' || coalesce(v_title, 'an event'),
          jsonb_build_object('event_id', p_event_id, 'invited_by', v_uid));

  return jsonb_build_object('success', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_active_team_member(p_contributor_id uuid, p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null
     and p_contributor_id is not null
     and p_roles is not null
     and exists (
       select 1
       from public.team_memberships tm
       join public.profiles p on p.id = tm.contributor_id
       where tm.contributor_id = p_contributor_id
         and tm.member_id = (select auth.uid())
         and tm.status = 'active'
         and tm.role = any (p_roles)
         and p.role = 'contributor'
         and p.contributor_status = 'approved'
         and coalesce(p.contributor_hidden, false) = false
         and p.deleted_at is null
     );
$function$;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null
     and exists (
       select 1
       from public.profiles
       where id = (select auth.uid())
         and role = 'admin'
     );
$function$;

CREATE OR REPLACE FUNCTION public.is_approved_contributor()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.profiles
    where id = auth.uid()
    and (role = 'admin' or (role = 'contributor' and contributor_status = 'approved'))
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_blocked(user_a uuid, user_b uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or (auth.uid() <> user_a and auth.uid() <> user_b) then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  return exists (
    select 1 from public.user_blocks
    where (blocker_id = user_a and blocked_id = user_b)
       or (blocker_id = user_b and blocked_id = user_a)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_considering_for_friend(p_other uuid, p_event uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select auth.uid() is not null
    and p_other is not null
    and p_event is not null
    and p_other <> auth.uid()
    and public.is_mutual_follow(p_other)
    and not exists (
      select 1 from public.user_blocks b
      where (b.blocker_id = auth.uid() and b.blocked_id = p_other)
         or (b.blocker_id = p_other and b.blocked_id = auth.uid())
    )
    and not exists (
      select 1 from public.profiles pr
      where pr.id = p_other
        and (pr.deleted_at is not null or pr.notification_prefs->>'share_considering' = 'false')
    )
    and exists (
      select 1 from public.events e
      where e.id = p_event
        and e.status = 'published'
        and coalesce(e.end_time, e.date + interval '1 day') >= now()
    )
    and exists (
      select 1 from public.rsvps r
      where r.user_id = p_other and r.event_id = p_event and r.status = 'considering'
    );
$function$;

CREATE OR REPLACE FUNCTION public.is_conversation_participant(conv_id uuid, uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or uid is distinct from auth.uid() then
    if coalesce(auth.role(), '') <> 'service_role' then
      return false;
    end if;
  end if;

  return exists (
    select 1
    from public.conversation_participants
    where conversation_id = conv_id
      and user_id = uid
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_mutual_follow(p_other uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select auth.uid() is not null
    and exists (select 1 from public.follows where follower_id = auth.uid() and followee_id = p_other)
    and exists (select 1 from public.follows where follower_id = p_other and followee_id = auth.uid());
$function$;

CREATE OR REPLACE FUNCTION public.is_organiser()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = auth.uid()
       AND role IN ('contributor', 'admin')
  );
$function$;

CREATE OR REPLACE FUNCTION public.log_search_term(p_term text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_term text := public.sanitise_search_term(p_term);
BEGIN
  IF v_term IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO search_term_stats (term, day, hits)
  VALUES (v_term, CURRENT_DATE, 1)
  ON CONFLICT (term, day)
    DO UPDATE SET hits = search_term_stats.hits + 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.mark_admin_viewing_started(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE contributor_access_requests
  SET viewing_started_at = COALESCE(viewing_started_at, now())
  WHERE id = p_request_id
    AND admin_id = auth.uid()
    AND status = 'approved'
    AND revoked_at IS NULL
    AND (expires_at IS NULL OR expires_at > now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.mark_my_terms_accepted()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.profiles
     set terms_accepted_at = now()
   where id = (select auth.uid())
     and terms_accepted_at is null;
$function$;

CREATE OR REPLACE FUNCTION public.mark_own_listing_claimed()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_email text;
  caller_confirmed timestamptz;
  ledger record;
  own_slug text;
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason', 'not_authenticated');
  end if;

  select email, email_confirmed_at into caller_email, caller_confirmed
    from auth.users where id = auth.uid();
  if caller_email is null or caller_email = '' or caller_confirmed is null then
    return jsonb_build_object('success', false, 'reason', 'email_not_verified');
  end if;

  select lc.* into ledger from public.listing_claims lc
   where lc.status = 'awaiting'
     and lc.placeholder_id = auth.uid()
     and lc.claim_email = lower(btrim(caller_email))
   for update;
  if not found then
    return jsonb_build_object('success', false, 'reason', 'nothing_to_mark');
  end if;

  update public.profiles set
    contributor_claimed_at = now(),
    contributor_claim_email = null
  where id = auth.uid()
    and role = 'contributor'
    and coalesce(contributor_hidden, false) = false
    and deleted_at is null
  returning contributor_slug into own_slug;
  if not found then
    return jsonb_build_object('success', false, 'reason', 'nothing_to_mark');
  end if;

  update public.listing_claims set
    status = 'confirmed', claimant_id = auth.uid(), decided_at = now()
  where id = ledger.id;

  return jsonb_build_object('success', true, 'slug', own_slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.moments_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select count(*) from public.moments where contributor_id = new.contributor_id and expires_at > now()) >= 5 then
    raise exception 'moments_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_event_field_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  parts text[] := array[]::text[];
  msg   text;
begin
  if coalesce(new.status, '') <> 'published' then
    return new;
  end if;

  if new.date is distinct from old.date then
    parts := array_append(parts, 'date');
  end if;
  if new.end_time is distinct from old.end_time then
    parts := array_append(parts, 'end time');
  end if;
  if new.location is distinct from old.location then
    parts := array_append(parts, 'venue');
  end if;
  if new.latitude is distinct from old.latitude
     or new.longitude is distinct from old.longitude then
    if not ('venue' = any(parts)) then
      parts := array_append(parts, 'location');
    end if;
  end if;
  if new.volunteer_openings is distinct from old.volunteer_openings then
    parts := array_append(parts, 'volunteer openings');
  end if;

  if array_length(parts, 1) is null then
    return new;
  end if;

  msg := 'Organiser updated the ' || array_to_string(parts, ', ') || '.';

  insert into public.event_updates (event_id, author_id, body, is_system, is_material)
  values (new.id, new.created_by, msg, true, true);

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_friends_on_rsvp_attending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  actor_name text;
  event_title text;
begin
  if new.status is distinct from 'attending' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status = 'attending' then
    return new;
  end if;

  select coalesce(full_name, 'Someone')
    into actor_name
    from public.profiles
   where id = new.user_id;

  select title
    into event_title
    from public.events
   where id = new.event_id;

  if event_title is null then
    return new;
  end if;

  insert into public.notifications (user_id, type, title, body, data)
  select
    f1.follower_id,
    'friend_attending',
    actor_name || ' is going to ' || event_title,
    'Tap to view the event',
    jsonb_build_object(
      'event_id', new.event_id,
      'actor_id', new.user_id
    )
  from public.follows f1
  join public.follows f2
    on f2.follower_id = f1.followee_id
   and f2.followee_id = f1.follower_id
  join public.profiles p
    on p.id = f1.follower_id
  where f1.followee_id = new.user_id
    and f1.follower_id <> new.user_id
    and coalesce((p.notification_prefs->>'friends_activity')::boolean, true) = true
    and not exists (
      select 1
        from public.notifications n
       where n.user_id = f1.follower_id
         and n.type   = 'friend_attending'
         and (n.data->>'event_id')::uuid = new.event_id
         and (n.data->>'actor_id')::uuid = new.user_id
         and n.created_at > now() - interval '24 hours'
    );

  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.notify_on_convince()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  sender_name text;
  event_title text;
  target_prefs jsonb;
begin
  select coalesce(nullif(btrim(full_name), ''), 'Someone')
    into sender_name
    from public.profiles
   where id = new.from_user_id;

  select title
    into event_title
    from public.events
   where id = new.event_id;

  if event_title is null then
    return new;
  end if;

  select notification_prefs
    into target_prefs
    from public.profiles
   where id = new.to_user_id;

  if coalesce((target_prefs->>'friends_activity')::boolean, true) = false then
    return new;
  end if;

  -- the guard: this sender already nudged this person about this event (withdrawn and sent again): do not notify twice
  if exists (
    select 1 from public.notifications n
     where n.user_id = new.to_user_id
       and n.type = 'friend_convince'
       and n.data->>'event_id' = new.event_id::text
       and n.data->>'from_user_id' = new.from_user_id::text
  ) then
    return new;
  end if;

  insert into public.notifications (user_id, type, title, body, data)
  values (
    new.to_user_id,
    'friend_convince',
    sender_name || ' thinks you should go to ' || event_title,
    'Tap to revisit the event',
    jsonb_build_object(
      'event_id',     new.event_id,
      'from_user_id', new.from_user_id
    )
  );

  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.on_role_change_side_effects()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.role is distinct from old.role then
    new.force_reauth_at := now();

    if old.role = 'citizen' and new.role = 'contributor' then
      new.bio_setup_required := true;
    end if;

    if old.role = 'contributor' and new.role <> 'contributor' then
      new.bio_setup_required := false;
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.on_rsvp_cancellation_increment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update events set cancellation_count = cancellation_count + 1 where id = new.event_id;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.peek_claimable_listing()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_email text;
  caller_confirmed timestamptz;
  ledger record;
  listing record;
  caller_ok boolean;
begin
  if auth.uid() is null then
    return jsonb_build_object('found', false, 'reason', 'not_authenticated');
  end if;

  select email, email_confirmed_at into caller_email, caller_confirmed
    from auth.users where id = auth.uid();
  if caller_email is null or caller_email = '' or caller_confirmed is null then
    return jsonb_build_object('found', false, 'reason', 'email_not_verified');
  end if;

  select lc.* into ledger from public.listing_claims lc
   where lc.status = 'awaiting'
     and lc.claim_email = lower(btrim(caller_email))
   limit 1;
  if not found then
    return jsonb_build_object('found', false);
  end if;

  select id, full_name, contributor_kind, contributor_category, logo_url, bio,
         contributor_no_fixed_location, physical_latitude, physical_longitude
    into listing from public.profiles
   where id = ledger.placeholder_id
     and role = 'contributor' and contributor_status = 'approved'
     and coalesce(contributor_hidden, false) = false and deleted_at is null;
  if not found then
    return jsonb_build_object('found', false);
  end if;

  if ledger.placeholder_id = auth.uid() then
    return jsonb_build_object(
      'found', true, 'mode', 'self', 'eligible', true,
      'name', listing.full_name, 'slug', ledger.slug, 'kind', listing.contributor_kind,
      'category', listing.contributor_category, 'logo_url', listing.logo_url,
      'created_at', ledger.created_at
    );
  end if;

  select (role = 'citizen' and contributor_status = 'not_applied') into caller_ok
    from public.profiles where id = auth.uid();

  return jsonb_build_object(
    'found', true, 'mode', 'attach', 'eligible', coalesce(caller_ok, false),
    'name', listing.full_name, 'slug', ledger.slug, 'kind', listing.contributor_kind,
    'category', listing.contributor_category, 'logo_url', listing.logo_url,
    'created_at', ledger.created_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.propose_team_owner_transfer(p_contributor_id uuid, p_proposed_owner_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller         uuid := auth.uid();
  v_is_owner       boolean;
  v_member_active  boolean;
  v_transfer_id    uuid;
  v_contributor_slug text;
  v_owner_name     text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_proposed_owner_id = p_contributor_id THEN
    RAISE EXCEPTION 'invalid_proposal';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM team_memberships
    WHERE contributor_id = p_contributor_id
      AND member_id      = v_caller
      AND role           = 'owner'
      AND status         = 'active'
  ) INTO v_is_owner;

  IF NOT v_is_owner THEN
    RAISE EXCEPTION 'not_owner';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM team_memberships
    WHERE contributor_id = p_contributor_id
      AND member_id      = p_proposed_owner_id
      AND status         = 'active'
      AND role           <> 'owner'
  ) INTO v_member_active;

  IF NOT v_member_active THEN
    RAISE EXCEPTION 'proposed_owner_not_active_member';
  END IF;

  UPDATE team_owner_transfers
  SET status       = 'cancelled',
      responded_at = now()
  WHERE contributor_id = p_contributor_id
    AND status         = 'pending';

  INSERT INTO team_owner_transfers
    (contributor_id, proposed_owner_id, proposed_by, status)
  VALUES
    (p_contributor_id, p_proposed_owner_id, v_caller, 'pending')
  RETURNING id INTO v_transfer_id;

  SELECT contributor_slug INTO v_contributor_slug FROM profiles WHERE id = p_contributor_id;
  SELECT full_name        INTO v_owner_name       FROM profiles WHERE id = v_caller;

  INSERT INTO notifications (user_id, type, title, body, data)
  VALUES (
    p_proposed_owner_id,
    'team_owner_transfer',
    'Ownership transfer proposed',
    COALESCE(v_owner_name, 'The owner') || ' has proposed transferring ownership to you.',
    jsonb_build_object(
      'transfer_id',       v_transfer_id,
      'contributor_id',    p_contributor_id,
      'contributor_handle', v_contributor_slug,
      'url',               '/account/team-invites'
    )
  );

  INSERT INTO activity_log
    (contributor_id, actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_contributor_id,
    v_caller,
    'team_owner_transfer_proposed',
    'team_owner_transfer',
    v_transfer_id::text,
    jsonb_build_object('proposed_owner_id', p_proposed_owner_id)
  );

  RETURN v_transfer_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.purge_old_activity_logs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM activity_log
  WHERE created_at < now() - interval '90 days';
END;
$function$;

CREATE OR REPLACE FUNCTION public.purge_old_analytics()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM contributor_analytics
  WHERE date < CURRENT_DATE - interval '1 year';

  DELETE FROM rsvp_cancellations
  WHERE cancelled_at < CURRENT_DATE - interval '90 days';

  DELETE FROM shares
  WHERE created_at < CURRENT_DATE - interval '90 days';
END;
$function$;

