 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM search_term_stats
  WHERE day < CURRENT_DATE - interval '180 days';
END;
$function$;

CREATE OR REPLACE FUNCTION public.recipient_follows_me(p_recipient uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select auth.uid() is not null and (
    exists (select 1 from public.follows f where f.follower_id = p_recipient and f.followee_id = auth.uid())
    or exists (
      select 1
      from public.place_follows pf
      join public.places pl on pl.id = pf.place_id
      where pf.user_id = p_recipient and pl.created_by = auth.uid()
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.recompute_map_prominence()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  k_event numeric := 4.0;
  k_place numeric := 3.0;
BEGIN
  WITH counts AS (
    SELECT
      e.id,
      COALESCE(r.n, 0)  AS rsvps,
      COALESCE(c.n, 0)  AS comments,
      COALESCE(v.n, 0)  AS views
    FROM events e
    LEFT JOIN (
      SELECT event_id, COUNT(*) AS n FROM rsvps
      WHERE status = 'attending' GROUP BY event_id
    ) r ON r.event_id = e.id
    LEFT JOIN (
      SELECT event_id, COUNT(*) AS n FROM comments
      WHERE event_id IS NOT NULL GROUP BY event_id
    ) c ON c.event_id = e.id
    LEFT JOIN (
      SELECT event_id, COUNT(*) AS n FROM event_views
      WHERE viewed_at >= now() - INTERVAL '90 days' GROUP BY event_id
    ) v ON v.event_id = e.id
  ), scored AS (
    SELECT
      id,
      ( 1.0 * ln(1 + rsvps)
      + 0.8 * ln(1 + comments)
      + 0.3 * ln(1 + views) ) AS raw
    FROM counts
  )
  UPDATE events e
  SET prominence_base = round((s.raw / (s.raw + k_event))::numeric, 4)
  FROM scored s
  WHERE s.id = e.id
    AND e.prominence_base IS DISTINCT FROM round((s.raw / (s.raw + k_event))::numeric, 4);

  WITH counts AS (
    SELECT
      p.id,
      COALESCE(f.n, 0)  AS follows,
      COALESCE(rv.n, 0) AS reviews
    FROM places p
    LEFT JOIN (
      SELECT place_id, COUNT(*) AS n FROM place_follows GROUP BY place_id
    ) f ON f.place_id = p.id
    LEFT JOIN (
      SELECT place_id, COUNT(*) AS n FROM reviews
      WHERE place_id IS NOT NULL GROUP BY place_id
    ) rv ON rv.place_id = p.id
  ), scored AS (
    SELECT
      id,
      ( 1.0 * ln(1 + follows)
      + 0.8 * ln(1 + reviews) ) AS raw
    FROM counts
  )
  UPDATE places p
  SET prominence_base = round((s.raw / (s.raw + k_place))::numeric, 4)
  FROM scored s
  WHERE s.id = p.id
    AND p.prominence_base IS DISTINCT FROM round((s.raw / (s.raw + k_place))::numeric, 4);
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_event_impression(p_user_id uuid, p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'unauthorized' using errcode = 'insufficient_privilege';
  end if;

  insert into event_impressions (user_id, event_id)
  values (p_user_id, p_event_id)
  on conflict do nothing;

  if found then
    update events set impression_count = impression_count + 1 where id = p_event_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_admin_elevation(p_request_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_request public.pending_admin_elevations%rowtype;
  v_actor   uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not public.is_admin() then
    raise exception 'Admin role required' using errcode = '42501';
  end if;

  select * into v_request
    from public.pending_admin_elevations
   where id = p_request_id
   for update;

  if not found then
    raise exception 'Elevation request not found' using errcode = 'P0002';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'Elevation request is not pending (status = %)', v_request.status
      using errcode = 'P0001';
  end if;

  update public.pending_admin_elevations
     set status = 'rejected',
         approved_by = v_actor,
         approved_at = now(),
         rejection_reason = coalesce(nullif(trim(p_reason), ''), null)
   where id = p_request_id;

  return p_request_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_event_cohost(p_event_id uuid, p_contributor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then return jsonb_build_object('success', false, 'reason', 'not_authenticated'); end if;

  delete from public.event_cohosts c
   where c.event_id = p_event_id and c.contributor_id = p_contributor_id
     and (c.contributor_id = v_uid or c.invited_by = v_uid or (select public.is_admin()));
  if not found then return jsonb_build_object('success', false, 'reason', 'not_found'); end if;
  return jsonb_build_object('success', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.respond_event_cohost(p_event_id uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_inviter uuid;
begin
  if v_uid is null then return jsonb_build_object('success', false, 'reason', 'not_authenticated'); end if;

  update public.event_cohosts
     set status = case when p_accept then 'accepted' else 'declined' end, responded_at = now()
   where event_id = p_event_id and contributor_id = v_uid and status = 'invited'
   returning invited_by into v_inviter;
  if not found then return jsonb_build_object('success', false, 'reason', 'no_open_invitation'); end if;

  insert into public.notifications (user_id, type, title, body, data)
  values (v_inviter, 'cohost_invite_response',
          case when p_accept then 'Co-host invitation accepted' else 'Co-host invitation declined' end,
          'Your co-host invitation was ' || case when p_accept then 'accepted.' else 'declined.' end,
          jsonb_build_object('event_id', p_event_id, 'contributor_id', v_uid, 'accepted', p_accept));

  return jsonb_build_object('success', true, 'status', case when p_accept then 'accepted' else 'declined' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.respond_team_invite(p_membership_id uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contributor_id uuid;
  v_member_id      uuid;
  v_role           text;
  v_new_status     text;
  v_contributor_slug text;
  v_member_name    text;
BEGIN
  IF p_action NOT IN ('accept', 'decline') THEN
    RAISE EXCEPTION 'invalid_action';
  END IF;

  SELECT contributor_id, member_id, role
    INTO v_contributor_id, v_member_id, v_role
  FROM team_memberships
  WHERE id = p_membership_id
    AND status = 'pending';

  IF v_contributor_id IS NULL THEN
    RAISE EXCEPTION 'invite_not_found';
  END IF;

  IF v_member_id <> auth.uid() THEN
    RAISE EXCEPTION 'not_invitee';
  END IF;

  IF p_action = 'accept' THEN
    v_new_status := 'active';
  ELSE
    v_new_status := 'declined';
  END IF;

  UPDATE team_memberships
  SET status       = v_new_status,
      responded_at = now(),
      updated_at   = now()
  WHERE id = p_membership_id;

  SELECT contributor_slug INTO v_contributor_slug
  FROM profiles WHERE id = v_contributor_id;

  SELECT full_name INTO v_member_name
  FROM profiles WHERE id = v_member_id;

  INSERT INTO notifications (user_id, type, title, body, data)
  VALUES (
    v_contributor_id,
    'team_invite_response',
    CASE WHEN p_action = 'accept' THEN 'Team invite accepted' ELSE 'Team invite declined' END,
    COALESCE(v_member_name, 'Someone') ||
      CASE WHEN p_action = 'accept'
           THEN ' joined your team as ' || v_role || '.'
           ELSE ' declined your team invite.' END,
    jsonb_build_object(
      'membership_id', p_membership_id,
      'member_id', v_member_id,
      'role', v_role,
      'action', p_action,
      'url', CASE WHEN v_contributor_slug IS NOT NULL
                  THEN '/c/' || v_contributor_slug || '/dashboard/team'
                  ELSE '/dashboard' END
    )
  );

  INSERT INTO activity_log
    (contributor_id, actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    v_contributor_id,
    v_member_id,
    CASE WHEN p_action = 'accept' THEN 'team_invite_accepted' ELSE 'team_invite_declined' END,
    'team_membership',
    p_membership_id::text,
    jsonb_build_object('role', v_role)
  );

  RETURN v_new_status;
END;
$function$;

CREATE OR REPLACE FUNCTION public.respond_team_owner_transfer(p_transfer_id uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller            uuid := auth.uid();
  v_contributor_id    uuid;
  v_proposed_owner_id uuid;
  v_proposer_id       uuid;
  v_status            text;
  v_new_status        text;
  v_prior_owner_id    uuid;
  v_acceptor_name     text;
  v_contributor_slug  text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_action NOT IN ('accept', 'decline') THEN
    RAISE EXCEPTION 'invalid_action';
  END IF;

  SELECT contributor_id, proposed_owner_id, proposed_by, status
    INTO v_contributor_id, v_proposed_owner_id, v_proposer_id, v_status
  FROM team_owner_transfers
  WHERE id = p_transfer_id
  FOR UPDATE;

  IF v_contributor_id IS NULL THEN
    RAISE EXCEPTION 'transfer_not_found';
  END IF;

  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'transfer_already_resolved';
  END IF;

  IF v_proposed_owner_id <> v_caller THEN
    RAISE EXCEPTION 'not_proposed_owner';
  END IF;

  IF p_action = 'decline' THEN
    UPDATE team_owner_transfers
    SET status       = 'declined',
        responded_at = now()
    WHERE id = p_transfer_id;

    INSERT INTO notifications (user_id, type, title, body, data)
    VALUES (
      v_proposer_id,
      'team_invite_response',
      'Ownership transfer declined',
      'The proposed owner declined the transfer.',
      jsonb_build_object(
        'transfer_id',    p_transfer_id,
        'contributor_id', v_contributor_id,
        'action',         'decline'
      )
    );

    INSERT INTO activity_log
      (contributor_id, actor_id, action, entity_type, entity_id, metadata)
    VALUES (
      v_contributor_id,
      v_caller,
      'team_owner_transfer_declined',
      'team_owner_transfer',
      p_transfer_id::text,
      jsonb_build_object('proposed_owner_id', v_proposed_owner_id)
    );

    RETURN 'declined';
  END IF;

  SELECT member_id INTO v_prior_owner_id
  FROM team_memberships
  WHERE contributor_id = v_contributor_id
    AND role           = 'owner'
    AND status         = 'active'
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF v_prior_owner_id IS NULL THEN
    RAISE EXCEPTION 'no_current_owner';
  END IF;

  UPDATE team_memberships
  SET role       = 'editor',
      updated_at = now()
  WHERE contributor_id = v_contributor_id
    AND member_id      = v_prior_owner_id
    AND role           = 'owner'
    AND status         = 'active';

  UPDATE team_memberships
  SET role         = 'owner',
      responded_at = now(),
      updated_at   = now()
  WHERE contributor_id = v_contributor_id
    AND member_id      = v_caller
    AND status         = 'active';

  UPDATE team_owner_transfers
  SET status       = 'accepted',
      responded_at = now()
  WHERE id = p_transfer_id;

  SELECT full_name        INTO v_acceptor_name    FROM profiles WHERE id = v_caller;
  SELECT contributor_slug INTO v_contributor_slug FROM profiles WHERE id = v_contributor_id;

  INSERT INTO notifications (user_id, type, title, body, data)
  VALUES (
    v_proposer_id,
    'team_invite_response',
    'Ownership transferred',
    COALESCE(v_acceptor_name, 'The proposed owner') || ' accepted ownership. You are now an editor.',
    jsonb_build_object(
      'transfer_id',       p_transfer_id,
      'contributor_id',    v_contributor_id,
      'contributor_handle', v_contributor_slug,
      'action',            'accept',
      'url',               CASE WHEN v_contributor_slug IS NOT NULL
                                THEN '/c/' || v_contributor_slug || '/dashboard/team'
                                ELSE '/dashboard' END
    )
  );

  INSERT INTO notifications (user_id, type, title, body, data)
  VALUES (
    v_caller,
    'team_invite_response',
    'You are now the owner',
    'You accepted ownership. You now have full owner access.',
    jsonb_build_object(
      'transfer_id',       p_transfer_id,
      'contributor_id',    v_contributor_id,
      'contributor_handle', v_contributor_slug,
      'url',               CASE WHEN v_contributor_slug IS NOT NULL
                                THEN '/c/' || v_contributor_slug || '/dashboard'
                                ELSE '/dashboard' END
    )
  );

  INSERT INTO activity_log
    (contributor_id, actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    v_contributor_id,
    v_caller,
    'team_owner_transfer_accepted',
    'team_owner_transfer',
    p_transfer_id::text,
    jsonb_build_object(
      'prior_owner_id', v_prior_owner_id,
      'new_owner_id',   v_caller
    )
  );

  RETURN 'accepted';
END;
$function$;

CREATE OR REPLACE FUNCTION public.safe_rsvp(p_user_id uuid, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_visibility text;
  v_max int;
  v_current int;
  v_remaining int;
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  select status, visibility, max_attendees
    into v_status, v_visibility, v_max
  from public.events
  where id = p_event_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'error', 'Event not found', 'status', 404);
  end if;

  if v_visibility = 'private' and not public.caller_may_read_private_event(p_event_id) then
    return jsonb_build_object('success', false, 'error', 'Event not found', 'status', 404);
  end if;

  if v_status <> 'published' then
    return jsonb_build_object('success', false, 'error',
      'Cannot RSVP to a ' || v_status || ' event', 'status', 400);
  end if;

  if v_max is not null then
    select count(*)::int into v_current
    from public.rsvps
    where event_id = p_event_id;

    if v_current >= v_max then
      return jsonb_build_object('success', false, 'error', 'Event is full',
        'remaining', 0, 'status', 409);
    end if;

    v_remaining := v_max - v_current - 1;
  else
    v_remaining := null;
  end if;

  begin
    insert into public.rsvps (user_id, event_id, location_snapshot)
    values (
      p_user_id,
      p_event_id,
      (select connect_home_province from public.profiles where id = p_user_id)
    );
  exception when unique_violation then
    return jsonb_build_object('success', false, 'error',
      'Already RSVPed to this event', 'status', 409);
  end;

  return jsonb_build_object('success', true, 'remaining', v_remaining, 'status', 201);
end;
$function$;

CREATE OR REPLACE FUNCTION public.sanitise_search_term(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text;
BEGIN
  IF p_raw IS NULL THEN
    RETURN NULL;
  END IF;
  v := regexp_replace(p_raw, '[\x00-\x1F\x7F]', ' ', 'g');
  v := regexp_replace(v, '\s+', ' ', 'g');
  v := btrim(lower(v));
  IF char_length(v) < 2 THEN
    RETURN NULL;
  END IF;
  IF char_length(v) > 80 THEN
    v := substr(v, 1, 80);
    v := btrim(v);
  END IF;
  IF v !~ '[a-z0-9]' THEN
    RETURN NULL;
  END IF;
  RETURN v;
END;
$function$;

CREATE OR REPLACE FUNCTION public.saved_items_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select count(*) from public.saved_items where user_id = new.user_id) >= 500 then
    raise exception 'saved_items_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_contributors(q text, kinds text[] DEFAULT NULL::text[], location_query text DEFAULT NULL::text, category_slug text DEFAULT NULL::text, sort_by text DEFAULT 'auto'::text, result_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, full_name text, contributor_slug text, contributor_kind text, logo_url text, avatar_url text, physical_address text, bio text, followers_count bigint, similarity real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
  WITH norm AS (
    SELECT
      nullif(lower(coalesce(q, '')), '')              AS qn,
      nullif(lower(coalesce(location_query, '')), '') AS locn
  ), esc AS (
    SELECT
      qn,
      locn,
      replace(replace(replace(qn,   '\', '\\'), '%', '\%'), '_', '\_') AS qn_like,
      replace(replace(replace(locn, '\', '\\'), '%', '\%'), '_', '\_') AS locn_like
    FROM norm
  ), base AS (
    SELECT
      p.id,
      p.full_name,
      p.contributor_slug,
      p.contributor_kind,
      p.logo_url,
      p.avatar_url,
      p.physical_address,
      CASE
        WHEN p.bio IS NULL THEN NULL
        WHEN char_length(p.bio) <= 160 THEN p.bio
        ELSE regexp_replace(substr(p.bio, 1, 160), '\s+\S*$', '') || '…'
      END AS bio,
      public.follower_count_public(p.id) AS followers_count,
      CASE
        WHEN (SELECT qn FROM esc) IS NULL THEN 0
        ELSE greatest(
          extensions.word_similarity((SELECT qn FROM esc),
                                     lower(coalesce(p.full_name, ''))),
          extensions.similarity(lower(coalesce(p.full_name, '')),
                                (SELECT qn FROM esc))
        )
      END::real AS similarity
    FROM public.profiles p
    WHERE p.role = 'contributor'
      AND p.contributor_status = 'approved'
      AND p.contributor_slug IS NOT NULL
      AND (
        (SELECT qn FROM esc) IS NULL
        OR extensions.word_similarity((SELECT qn FROM esc),
                                      lower(coalesce(p.full_name, ''))) >= 0.3
        OR lower(coalesce(p.full_name, '')) ILIKE '%' || (SELECT qn_like FROM esc) || '%' ESCAPE '\'
        OR lower(coalesce(p.bio, ''))       ILIKE '%' || (SELECT qn_like FROM esc) || '%' ESCAPE '\'
      )
      AND (kinds IS NULL OR p.contributor_kind = ANY(kinds))
      AND (
        (SELECT locn FROM esc) IS NULL
        OR lower(coalesce(p.physical_address, '')) ILIKE '%' || (SELECT locn_like FROM esc) || '%' ESCAPE '\'
      )
      AND (
        category_slug IS NULL
        OR EXISTS (
          SELECT 1
            FROM public.events e
           WHERE e.created_by = p.id
             AND e.category   = category_slug
        )
      )
  )
  SELECT *
  FROM base
  ORDER BY
    CASE
      WHEN sort_by = 'similarity'
        OR (sort_by = 'auto' AND (SELECT qn FROM esc) IS NOT NULL)
      THEN base.similarity
    END DESC NULLS LAST,
    CASE
      WHEN sort_by IN ('followers', 'auto')
      THEN base.followers_count
    END DESC NULLS LAST,
    base.full_name ASC
  LIMIT greatest(1, least(coalesce(result_limit, 25), 100));
$function$;

CREATE OR REPLACE FUNCTION public.service_areas_check_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_parent_level text;
begin
  if new.parent_id is null then
    return new;
  end if;
  select a.level into v_parent_level from public.service_areas a where a.id = new.parent_id;
  if (new.level = 'place' and v_parent_level is distinct from 'province')
     or (new.level = 'suburb' and v_parent_level is distinct from 'place') then
    raise exception 'service area % has the wrong kind of parent', new.slug using errcode = '23514';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.serving_area_listings(p_area_id uuid, p_also_limit integer DEFAULT 5)
 RETURNS TABLE(section text, contributor_id uuid, full_name text, contributor_slug text, contributor_kind text, contributor_category text, avatar_url text, logo_url text, matched_area_id uuid, matched_area_name text, matched_level text, centre_area_name text, radius_km integer, distance_km numeric, presence text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with recursive chain as (
    select a.id, a.parent_id, a.level, a.name, a.centroid_lat, a.centroid_lng, 0 as depth
      from public.service_areas a where a.id = p_area_id
    union all
    select a.id, a.parent_id, a.level, a.name, a.centroid_lat, a.centroid_lng, c.depth + 1
      from public.service_areas a join chain c on a.id = c.parent_id
  ),
  live as (
    select p.id, p.full_name, p.contributor_slug, p.contributor_kind, p.contributor_category, p.avatar_url, p.logo_url,
           p.physical_latitude, p.physical_longitude,
           (coalesce(p.contributor_no_fixed_location, false) = false
              and p.physical_latitude is not null and p.physical_longitude is not null) as has_pin,
           coalesce(pr.presence, 'online') as presence
      from public.profiles p
      left join public.contributor_service_presence pr on pr.contributor_id = p.id
     where p.role = 'contributor' and p.contributor_status = 'approved'
       and coalesce(p.contributor_hidden, false) = false and p.deleted_at is null
  ),
  main as (
    select distinct on (l.id)
           l.id, l.full_name, l.contributor_slug, l.contributor_kind, l.contributor_category, l.avatar_url, l.logo_url,
           l.presence, c.id as matched_id, c.name as matched_name, c.level as matched_level
      from chain c
      join public.contributor_service_areas csa on csa.area_id = c.id
      join live l on l.id = csa.contributor_id
     where not l.has_pin
     order by l.id, c.depth
  ),
  here as (select centroid_lat, centroid_lng from chain where depth = 0),
  reach as (
    select l.id, l.full_name, l.contributor_slug, l.contributor_kind, l.contributor_category, l.avatar_url, l.logo_url,
           l.has_pin, l.presence, r.radius_km, ca.name as centre_name,
           6371.0 * 2 * asin(least(1.0, sqrt(
             power(sin(radians(h.centroid_lat - cp.lat) / 2), 2)
             + cos(radians(cp.lat)) * cos(radians(h.centroid_lat)) * power(sin(radians(h.centroid_lng - cp.lng) / 2), 2)
           ))) as d
      from public.contributor_service_radius r
      join live l on l.id = r.contributor_id
      left join public.service_areas ca on ca.id = r.centre_area_id
      cross join here h
      cross join lateral (
        select coalesce(ca.centroid_lat, case when l.has_pin then l.physical_latitude end) as lat,
               coalesce(ca.centroid_lng, case when l.has_pin then l.physical_longitude end) as lng
      ) cp
     where cp.lat is not null and cp.lng is not null
       and not exists (select 1 from main m where m.id = l.id)
  )
  select 'main'::text, m.id, m.full_name, m.contributor_slug, m.contributor_kind, m.contributor_category,
         m.avatar_url, m.logo_url, m.matched_id, m.matched_name, m.matched_level,
         null::text, null::integer, null::numeric, m.presence
    from main m
  union all
  select * from (
    select 'also'::text, x.id, x.full_name, x.contributor_slug, x.contributor_kind, x.contributor_category,
           x.avatar_url, x.logo_url, null::uuid, null::text, null::text,
           x.centre_name, x.radius_km, round(x.d::numeric, 1),
           case when x.has_pin then null else x.presence end
      from reach x
     where x.d <= x.radius_km
     order by x.d, x.full_name, x.id
     limit greatest(0, least(coalesce(p_also_limit, 5), 20))
  ) also_rows;
$function$;

CREATE OR REPLACE FUNCTION public.set_broadcast_audience_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  select count(*)::integer into new.audience_size_at_post
  from follows
  where followee_id = new.contributor_id;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_contributor_hidden(_user_id uuid, _hidden boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then
    return jsonb_build_object('success', false, 'reason', 'not_admin');
  end if;

  update public.profiles
    set contributor_hidden = _hidden
    where id = _user_id and role = 'contributor';

  if not found then
    return jsonb_build_object('success', false, 'reason', 'not_found');
  end if;

  return jsonb_build_object('success', true, 'user_id', _user_id, 'hidden', _hidden);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_rsvp_notify_updates(p_event_id uuid, p_notify boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_rows integer;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_event_id is null or p_notify is null then
    raise exception 'invalid_arguments' using errcode = '22023';
  end if;

  update public.rsvps
    set notify_updates = p_notify
    where user_id = v_uid
      and event_id = p_event_id;

  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_service_areas(p_contributor_id uuid, p_area_ids uuid[], p_radius_km integer DEFAULT NULL::integer, p_radius_centre_area_id uuid DEFAULT NULL::uuid, p_presence text DEFAULT 'online'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid     uuid := (select auth.uid());
  v_role    text;
  v_status  text;
  v_deleted timestamptz;
  v_has_pin boolean;
  v_ids     uuid[];
  v_known   integer;
  v_centre  uuid;
begin
  if v_uid is null then
    return jsonb_build_object('success', false, 'reason', 'not_authenticated');
  end if;
  if p_contributor_id is null then
    return jsonb_build_object('success', false, 'reason', 'not_found');
  end if;
  if not (
    v_uid = p_contributor_id
    or public.is_active_team_member(p_contributor_id, array['editor'])
    or (select public.is_admin())
  ) then
    return jsonb_build_object('success', false, 'reason', 'not_allowed');
  end if;

  select p.role, p.contributor_status, p.deleted_at,
         (coalesce(p.contributor_no_fixed_location, false) = false
            and p.physical_latitude is not null and p.physical_longitude is not null)
    into v_role, v_status, v_deleted, v_has_pin
    from public.profiles p where p.id = p_contributor_id;
  if not found or v_deleted is not null then
    return jsonb_build_object('success', false, 'reason', 'not_found');
  end if;
  if not ((v_role = 'contributor' and v_status = 'approved') or v_status = 'pending') then
    return jsonb_build_object('success', false, 'reason', 'not_a_contributor');
  end if;
  if v_status = 'pending' then
    select (coalesce(a.no_fixed_location, false) = false
              and a.physical_latitude is not null and a.physical_longitude is not null)
      into v_has_pin
      from public.contributor_applications a
     where a.user_id = p_contributor_id and a.status = 'pending'
     order by a.submitted_at desc limit 1;
    v_has_pin := coalesce(v_has_pin, false);
  end if;

  if p_presence is null or p_presence not in ('online', 'no_fixed_place') then
    return jsonb_build_object('success', false, 'reason', 'invalid_presence');
  end if;

  select coalesce(array_agg(distinct x), '{}'::uuid[]) into v_ids from unnest(coalesce(p_area_ids, '{}'::uuid[])) as x where x is not null;
  if cardinality(v_ids) > 20 then
    return jsonb_build_object('success', false, 'reason', 'too_many_areas');
  end if;
  select count(*) into v_known from public.service_areas a where a.id = any (v_ids);
  if v_known <> cardinality(v_ids) then
    return jsonb_build_object('success', false, 'reason', 'unknown_area');
  end if;

  if p_radius_km is not null then
    if p_radius_km < 1 or p_radius_km > 100 then
      return jsonb_build_object('success', false, 'reason', 'radius_out_of_range');
    end if;
    v_centre := p_radius_centre_area_id;
    if v_centre is not null then
      if not (v_centre = any (v_ids)) then
        return jsonb_build_object('success', false, 'reason', 'centre_not_ticked');
      end if;
    elsif cardinality(v_ids) > 0 and not v_has_pin then
      select a.id into v_centre
        from public.service_areas a
       where a.id = any (v_ids)
       order by (case a.level when 'suburb' then 3 when 'place' then 2 else 1 end) desc, a.name, a.id
       limit 1;
    elsif not v_has_pin then
      return jsonb_build_object('success', false, 'reason', 'radius_needs_centre');
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_contributor_id::text, 195));

  delete from public.contributor_service_areas c
   where c.contributor_id = p_contributor_id and not (c.area_id = any (v_ids));
  insert into public.contributor_service_areas (contributor_id, area_id)
    select p_contributor_id, x from unnest(v_ids) as x
    on conflict (contributor_id, area_id) do nothing;

  if p_radius_km is null then
    delete from public.contributor_service_radius r where r.contributor_id = p_contributor_id;
  else
    insert into public.contributor_service_radius (contributor_id, radius_km, centre_area_id)
      values (p_contributor_id, p_radius_km, v_centre)
      on conflict (contributor_id) do update
        set radius_km = excluded.radius_km, centre_area_id = excluded.centre_area_id, updated_at = now();
  end if;

  if cardinality(v_ids) = 0 and p_radius_km is null then
    delete from public.contributor_service_presence pr where pr.contributor_id = p_contributor_id;
  else
    insert into public.contributor_service_presence (contributor_id, presence)
      values (p_contributor_id, p_presence)
      on conflict (contributor_id) do update set presence = excluded.presence, updated_at = now();
  end if;

  return jsonb_build_object(
    'success', true,
    'area_ids', to_jsonb(v_ids),
    'radius_km', p_radius_km,
    'radius_centre_area_id', case when p_radius_km is null then null else v_centre end,
    'presence', p_presence
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_event_category_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.category IS NOT NULL AND NEW.category_id IS NULL THEN
    SELECT id INTO NEW.category_id FROM public.categories WHERE slug = NEW.category;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.tg_bubble_from_broadcast()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.entity_type = 'event' and exists (
    select 1 from public.events e
    where e.id = new.entity_id
      and e.visibility = 'public'
      and e.status in ('published', 'cancelled')
  ) then
    insert into public.map_bubbles (event_id, body, source)
    values (new.entity_id, left(new.body, 160), 'broadcast');
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tg_bubble_from_event_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from public.events e
    where e.id = new.event_id
      and e.visibility = 'public'
      and e.status in ('published', 'cancelled')
  ) then
    insert into public.map_bubbles (event_id, body, source)
    values (new.event_id, left(new.body, 160), 'event_update');
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_consider(p_user_id uuid, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing uuid;
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'unauthorized' using errcode = '42501';
  end if;

  select id into v_existing
  from public.rsvps
  where user_id = p_user_id and event_id = p_event_id;

  if v_existing is not null then
    delete from public.rsvps
    where id = v_existing and status = 'considering';
    return jsonb_build_object('success', true, 'action', 'removed');
  end if;

  if exists (
    select 1 from public.events e
    where e.id = p_event_id and e.visibility = 'private'
  ) and not public.caller_may_read_private_event(p_event_id) then
    return jsonb_build_object('success', false, 'error', 'Event not found', 'status', 404);
  end if;

  insert into public.rsvps (user_id, event_id, status)
  values (p_user_id, p_event_id, 'considering');
  return jsonb_build_object('success', true, 'action', 'added');
end;
$function$;

CREATE OR REPLACE FUNCTION public.trending_events(lim integer DEFAULT 5)
 RETURNS TABLE(event_id uuid, rsvp_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.event_id, count(*) as rsvp_count
  from public.rsvps r
  join public.events e on e.id = r.event_id
  where e.status = 'published' and e.date >= now()
  group by r.event_id
  order by rsvp_count desc
  limit lim;
$function$;

CREATE OR REPLACE FUNCTION public.update_contributor_public_profile(p_contributor_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_key text;
  v_allowed constant text[] := array[
    'bio',
    'website_url',
    'instagram_handle',
    'facebook_url',
    'tiktok_handle',
    'youtube_url',
    'x_handle',
    'linkedin_url',
    'whatsapp_number',
    'physical_address',
    'physical_latitude',
    'physical_longitude',
    'contributor_no_fixed_location',
    'logo_url',
    'gallery_urls',
    'contributor_contact_email',
    'contributor_category',
    'open_to_collaborate'
  ];
  v_lat double precision;
  v_lng double precision;
  v_gallery jsonb;
  v_item jsonb;
  v_url text;
begin
  if v_uid is null or not public.is_active_team_member(p_contributor_id, array['editor']) then
    raise exception 'unauthorized' using errcode = '42501';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'invalid_patch' using errcode = '22023';
  end if;

  for v_key in select jsonb_object_keys(p_patch)
  loop
    if not (v_key = any (v_allowed)) then
      raise exception 'forbidden_field' using errcode = '42501';
    end if;
  end loop;

  if p_patch ? 'bio' and p_patch->>'bio' is not null and char_length(p_patch->>'bio') > 2000 then
    raise exception 'invalid_field' using errcode = '22023';
  end if;
  if p_patch ? 'physical_address' and p_patch->>'physical_address' is not null and char_length(p_patch->>'physical_address') > 500 then
    raise exception 'invalid_field' using errcode = '22023';
  end if;
  if p_patch ? 'contributor_category' and p_patch->>'contributor_category' is not null and char_length(p_patch->>'contributor_category') > 80 then
    raise exception 'invalid_field' using errcode = '22023';
  end if;
  if p_patch ? 'contributor_contact_email' and p_patch->>'contributor_contact_email' is not null and char_length(p_patch->>'contributor_contact_email') > 254 then
    raise exception 'invalid_field' using errcode = '22023';
  end if;

  if p_patch ? 'website_url' and p_patch->>'website_url' is not null and p_patch->>'website_url' !~ '^https?://' then
    raise exception 'invalid_field' using errcode = '22023';
  end if;
  if p_patch ? 'logo_url' and p_patch->>'logo_url' is not null and p_patch->>'logo_url' !~ '^https://' then
    raise exception 'invalid_field' using errcode = '22023';
  end if;

  if p_patch ? 'physical_latitude' and p_patch->'physical_latitude' <> 'null'::jsonb then
    v_lat := (p_patch->>'physical_latitude')::double precision;
    if v_lat < -90 or v_lat > 90 then
      raise exception 'invalid_field' using errcode = '22023';
    end if;
  end if;
  if p_patch ? 'physical_longitude' and p_patch->'physical_longitude' <> 'null'::jsonb then
    v_lng := (p_patch->>'physical_longitude')::double precision;
    if v_lng < -180 or v_lng > 180 then
      raise exception 'invalid_field' using errcode = '22023';
    end if;
  end if;

  if p_patch ? 'gallery_urls' and p_patch->'gallery_urls' <> 'null'::jsonb then
    v_gallery := p_patch->'gallery_urls';
    if jsonb_typeof(v_gallery) <> 'array' or jsonb_array_length(v_gallery) > 6 then
      raise exception 'invalid_field' using errcode = '22023';
    end if;
    for v_item in select value from jsonb_array_elements(v_gallery)
    loop
      if jsonb_typeof(v_item) <> 'string' then
        raise exception 'invalid_field' using errcode = '22023';
      end if;
      v_url := v_item #>> '{}';
      if v_url is null or v_url !~ '^https://' or char_length(v_url) > 2000 then
        raise exception 'invalid_field' using errcode = '22023';
      end if;
    end loop;
  end if;

  if p_patch ? 'open_to_collaborate' and jsonb_typeof(p_patch->'open_to_collaborate') <> 'boolean' then
    raise exception 'invalid_field' using errcode = '22023';
  end if;

  update public.profiles set
    bio = case when p_patch ? 'bio' then nullif(p_patch->>'bio', '') else bio end,
    website_url = case when p_patch ? 'website_url' then nullif(p_patch->>'website_url', '') else website_url end,
    instagram_handle = case when p_patch ? 'instagram_handle' then nullif(p_patch->>'instagram_handle', '') else instagram_handle end,
    facebook_url = case when p_patch ? 'facebook_url' then nullif(p_patch->>'facebook_url', '') else facebook_url end,
    tiktok_handle = case when p_patch ? 'tiktok_handle' then nullif(p_patch->>'tiktok_handle', '') else tiktok_handle end,
    youtube_url = case when p_patch ? 'youtube_url' then nullif(p_patch->>'youtube_url', '') else youtube_url end,
    x_handle = case when p_patch ? 'x_handle' then nullif(p_patch->>'x_handle', '') else x_handle end,
    linkedin_url = case when p_patch ? 'linkedin_url' then nullif(p_patch->>'linkedin_url', '') else linkedin_url end,
    whatsapp_number = case when p_patch ? 'whatsapp_number' then nullif(p_patch->>'whatsapp_number', '') else whatsapp_number end,
    physical_address = case
      when p_patch ? 'contributor_no_fixed_location' and (p_patch->>'contributor_no_fixed_location')::boolean then null
      when p_patch ? 'physical_address' then nullif(p_patch->>'physical_address', '')
      else physical_address
    end,
    physical_latitude = case
      when p_patch ? 'contributor_no_fixed_location' and (p_patch->>'contributor_no_fixed_location')::boolean then null
      when p_patch ? 'physical_latitude' and p_patch->'physical_latitude' = 'null'::jsonb then null
      when p_patch ? 'physical_latitude' then (p_patch->>'physical_latitude')::double precision
      else physical_latitude
    end,
    physical_longitude = case
      when p_patch ? 'contributor_no_fixed_location' and (p_patch->>'contributor_no_fixed_location')::boolean then null
      when p_patch ? 'physical_longitude' and p_patch->'physical_longitude' = 'null'::jsonb then null
      when p_patch ? 'physical_longitude' then (p_patch->>'physical_longitude')::double precision
      else physical_longitude
    end,
    contributor_no_fixed_location = case
      when p_patch ? 'contributor_no_fixed_location' then (p_patch->>'contributor_no_fixed_location')::boolean
      else contributor_no_fixed_location
    end,
    logo_url = case when p_patch ? 'logo_url' then nullif(p_patch->>'logo_url', '') else logo_url end,
    gallery_urls = case
      when p_patch ? 'gallery_urls' and p_patch->'gallery_urls' = 'null'::jsonb then null
      when p_patch ? 'gallery_urls' then p_patch->'gallery_urls'
      else gallery_urls
    end,
    contributor_contact_email = case
      when p_patch ? 'contributor_contact_email' then nullif(lower(p_patch->>'contributor_contact_email'), '')
      else contributor_contact_email
    end,
    contributor_category = case
      when p_patch ? 'contributor_category' then nullif(p_patch->>'contributor_category', '')
      else contributor_category
    end,
    open_to_collaborate = case
      when p_patch ? 'open_to_collaborate' then (p_patch->>'open_to_collaborate')::boolean
      else open_to_collaborate
    end
  where id = p_contributor_id;

  insert into public.activity_log (
    contributor_id, actor_id, actor_role, action, entity_type, entity_id, metadata
  ) values (
    p_contributor_id,
    v_uid,
    'team_editor',
    'update_profile',
    'profile',
    p_contributor_id::text,
    jsonb_build_object('fields', (select coalesce(jsonb_agg(k), '[]'::jsonb) from jsonb_object_keys(p_patch) as k))
  );

  return jsonb_build_object('success', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_conversation_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.conversations SET updated_at = now() WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_notification_prefs(delta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  allowed_keys text[] := array[
    'friends_activity',
    'event_reminders',
    'contributor_updates',
    'announcements',
    'weekly_digest',
    'share_considering'
  ];
  k text;
  v jsonb;
  sanitized jsonb := '{}'::jsonb;
  uid uuid := auth.uid();
  merged jsonb;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if jsonb_typeof(delta) is distinct from 'object' then
    raise exception 'delta must be a jsonb object' using errcode = '22023';
  end if;

  for k, v in select key, value from jsonb_each(delta) loop
    if not (k = any(allowed_keys)) then
      raise exception 'unknown preference key: %', k using errcode = '22023';
    end if;
    if jsonb_typeof(v) is distinct from 'boolean' then
      raise exception 'preference % must be boolean', k using errcode = '22023';
    end if;
    sanitized := sanitized || jsonb_build_object(k, v);
  end loop;

  update public.profiles
     set notification_prefs = coalesce(notification_prefs, jsonb_build_object(
            'friends_activity',    true,
            'event_reminders',     true,
            'contributor_updates', true,
            'announcements',       true,
            'weekly_digest',       true,
            'share_considering',   true
          )) || sanitized
   where id = uid
  returning notification_prefs into merged;

  if merged is null then
    raise exception 'profile not found' using errcode = 'P0002';
  end if;

  return merged;
end;
$function$;

reset search_path;
reset check_function_bodies;

insert into engine.schema_migrations (version, name) values ('0003', 'functions');
